def tas_prefixes(apps, schema_editor):
    """Project lead, 23 Oct 2026: references read TAS-<HO or branch initials>-<city code>-0001 (no city name).
    Certificates already issued keep the reference printed on them."""
    from apps.organisation.references import city_code, make_prefix

    Branch = apps.get_model("organisation", "Branch")
    Branch.objects.filter(code="fsd-samanabad").update(is_head_office=True)
    taken = set(Branch.objects.filter(reference_prefix__startswith="TAS-").values_list("reference_prefix", flat=True))
    for b in Branch.objects.order_by("pk"):
        b.city_code = (b.city_code or city_code(b.city)).upper()
        if not b.reference_prefix.startswith("TAS-"):
            b.reference_prefix = make_prefix(b.name, b.code, b.is_head_office, b.city, b.city_code, taken)
            taken.add(b.reference_prefix)
        b.save(update_fields=["city_code", "reference_prefix"])


